INSERT INTO proof_template (key,value) VALUES
('Title','SALES PROOF'),
('ETL_Text','ETL Listed for Safety (USA & Canada) This product proudly bears the ETL Listed Mark. This certification from Intertek — an OSHA-recognized Nationally Recognized Testing Laboratory (NRTL) — proves that this item has been independently tested and meets all applicable U.S. and Canadian product safety standards. The ETL mark is accepted by inspectors, retailers, and regulatory authorities across North America.'),
('Legal_Text','This design and engineering is submitted as our proposal, and the right to use or exhibit in any form, is not authorized without written permission by The Sign Store Online, Inc.'),
('Copyright_Text','Copyright {YEAR}. All Design/Images for The Sign Store Online, Inc.'),
('Approval_Label','Customer Approval Signature'),
('Date_Label','Date'),
('Watermark','On'),
('Watermark_Opacity','2'),
('Detail_Drawings','On'),
('Cover_Page','On'),
('Cover_Title','SALES PROOF PACKAGE'),
('Company_Name','The Sign Store Online, Inc.'),
('Company_Address','1836 Broadway, Macon, GA 31201'),
('Company_Phone','478-785-0610'),
('Company_Website','www.signstoremacon.com'),
('Company_Email',NULL),
('QA_Checklist','On'),
('QA_Final_Checks','Finished work matches the signed proof (every page)|Overall dimensions verified against the proof|Colors match the callouts (vinyl / paint / print)|Mounting hardware, patterns and templates included|Lit signs: ETL label applied and power supply tested|Clean, protected and labeled for install / pickup');
INSERT INTO readme (line_no,section,item,description) VALUES
(1,'VERSION 2.1.2 (PROOF PACKAGES)','VERSION 2.1.2 (PROOF PACKAGES)',NULL),
(2,'VERSION 2.1.2 (PROOF PACKAGES)','v2.1.2 Lit monument letters','MONUMENT_LETTERS: LIGHTING (Non-Lit / Front Lit / Halo Lit / Ground Lit) now picks the construction fields (Component_Schema). Detail_Drawings: LTR_FRONT_LIT and LTR_TRIMCAP also for front lit monument letters. Design_Guide: lit-sign rules include front lit monument letters.'),
(3,'VERSION 2.1.2 (PROOF PACKAGES)','v2.1 Monument letters, Sales Proof','New MONUMENT_LETTERS component (Component_Registry, Component_Schema) and optional Monument Letters section in Monument Signs (Product_Assembly). Detail_Drawings: MNT_TOP_PINNED, MNT_TOP_ADHESIVE; LTR_HALO_LIT also for halo monument letters. Design_Guide: L08. Proof_Template: Title = SALES PROOF, Cover_Title = SALES PROOF PACKAGE.'),
(4,'VERSION 2.1.2 (PROOF PACKAGES)','v2.0 Proof Library + new look','Saved_Proofs tab is created automatically on the first save (one row per revision; do not rename it). Proofs are stored in a "Proof Library" Drive folder next to this sheet. New Apps Script file: ProofLibrary. No other sheet changes.'),
(5,'VERSION 2.1.2 (PROOF PACKAGES)','v1.9.5 Multiple vinyl colors','+ Add Color on vinyl fields lists several colors in one section. No sheet changes.'),
(6,'VERSION 2.1.2 (PROOF PACKAGES)','v1.9.4 Cloud signs, dashboard','Cloud Letters products and the CLOUD component replaced by Cloud Sign - Front Lit / Halo Lit (CLOUD_SIGN_FL, CLOUD_SIGN_HALO): quantity + size instead of letters (Component_Registry, Component_Schema, Product_Assembly, Detail_Drawings, Design_Guide). Dashboard icons and color families are built into the app.'),
(7,'VERSION 2.1.2 (PROOF PACKAGES)','v1.9.3 Build Custom Table','Custom tables are built on screen and kept with the package only. No sheet changes.'),
(8,'VERSION 2.1.2 (PROOF PACKAGES)','v1.9.2 Cloud letters, EMC','New CLOUD_LETTERS_FL / CLOUD_LETTERS_HALO components (Component_Registry, Component_Schema, Detail_Drawings, Design_Guide); CLOUD is no longer a stand-alone tool. EMC fields rebuilt from production specs: 9.45" modules, pixel pitch, module / cabinet / back angle depths, calculated display size and depths. New field type calc; number fields can carry a unit in Options.'),
(9,'VERSION 2.1.2 (PROOF PACKAGES)','v1.9.1 Measure mode','Measurement lines only respond to the mouse in Measure mode. No sheet changes.'),
(10,'VERSION 2.1.2 (PROOF PACKAGES)','v1.9 Standoffs, clouds, raceways','Standoff model / size / finish on ACM, PVC, Acrylic, HDU and ADA (Component_Schema). New CLOUD component and Cloud Letters - Front Lit / Halo Lit products (Product_Assembly). RACEWAY SIZE on Channel Letters - Front Lit.'),
(11,'VERSION 2.1.2 (PROOF PACKAGES)','v1.8 Notes + quantities','Per-section Special Notes print beside that section''s table on the proof. Cover Package Contents shows quantities, e.g. "(x2) Main Menu Boards". No sheet changes.'),
(12,'VERSION 2.1.2 (PROOF PACKAGES)','v1.7 Section names','The red section titles in the proof builder are editable (default "Acrylic 1", "Acrylic 2" ...). The name prints on the proof, cover contents and QA checklist. No sheet changes.'),
(13,'VERSION 2.1.2 (PROOF PACKAGES)','Flow','1) Select any mix of products and components on the dashboard  2) Fill in specs  3) Add customer info  4) Generate Proof Package (zip of editable SVG + PNG per page).'),
(14,'VERSION 2.1.2 (PROOF PACKAGES)','All products migrated','The 10 original products are now components too (ACM_PANEL, CORO_SIGN, BANNER ...), each with a one-line Product_Assembly row. Product_Schema is kept for reference only; the current app does not read it.'),
(15,'VERSION 2.1.2 (PROOF PACKAGES)','Proof_Template','Fixed text printed on every proof page (title, ETL text, legal text, copyright). {YEAR} becomes the current year.'),
(16,'VERSION 2.1.2 (PROOF PACKAGES)','Hide_Values','Component_Schema column. Values listed here (e.g. None) are not printed on the proof.'),
(17,'VERSION 2.1.2 (PROOF PACKAGES)','color / fullcolor types','color = dropdown of color names with a swatch (colors from Finish_Colors). fullcolor = fixed ''Full Color Digital'' with a rainbow swatch.'),
(19,'WHAT CHANGED FROM THE ORIGINAL APP','WHAT CHANGED FROM THE ORIGINAL APP',NULL),
(20,'WHAT CHANGED FROM THE ORIGINAL APP','New engine','Complex products are now ASSEMBLIES of reusable COMPONENTS. The 10 existing Product_Schema products (ACM, Acrylic, Banner, Channel Letters - Front Lit, Coroplast, Cut Vinyl Decal, Digital Print Vinyl, HDU Sign, PVC Panel, PVC - Routed Letters) still run exactly as before.'),
(21,'WHAT CHANGED FROM THE ORIGINAL APP','Products moved','ADA Signs, Directional Signs, Lighted Cabinets, Monument Signs, Post and Panel Sign, Reverse / Halo Lit Channel Letters. Their old stub rows are kept in Retired_Schema_Stubs.'),
(22,'WHAT CHANGED FROM THE ORIGINAL APP','New product','Pole Sign = Pole + Pole Cover + Cabinet + Polycarbonate Face + Illumination (+ optional EMC).'),
(23,'WHAT CHANGED FROM THE ORIGINAL APP','Component tools','Every component with Show_As_Tool = Yes appears in the dropdown under ''Components'' and can be proofed on its own.'),
(25,'TABS','TABS',NULL),
(26,'TABS','Component_Registry','One row per component: ID, display name, tool on/off, repeatable, description.'),
(27,'TABS','Component_Schema','The fields of each component. Zone = preview column. Label = text shown on the proof. Type controls the input (see TYPES).'),
(28,'TABS','Product_Assembly','Which components make up each product, in order. Include = Required / Optional-On / Optional-Off (checkbox in the app). Repeatable = Yes adds an ''+ Add another'' button. Default_Overrides change a component''s defaults for that product only.'),
(29,'TABS','Page_Group','Product_Assembly column. Sections with the same Page_Group number share a proof page. Max 2 sections per page; a group with more is split across pages. Leftover single sections from neighboring groups are paired together.'),
(30,'TABS','Finish_Colors','Standard finishes (Black, Bronze, White...) and their swatch color. Any ''finish'' field also offers ''Custom Paint'' (SW / PMS picker).'),
(31,'TABS','Rowmark_Colors','Copied from SignOS REF_Colors_Rowmark. Used by ADA background and tactile color pickers.'),
(32,'TABS','ADA_Pictograms','Copied from SignOS REF_Pictograms. The proof draws the selected pictogram.'),
(33,'TABS','SignOS_Reference','SignOS SKUs behind the material options (posts, frames, sheet stock, LEDs, vinyl, ADA, hardware). The SignOS_Ref column in Component_Schema points here.'),
(35,'TYPES','TYPES',NULL),
(36,'TYPES','text / number','Free entry. On a number field, Options = a unit added after the value on the proof (e.g. " gives 1.5").'),
(37,'TYPES','calc','Read-only, calculated from other fields in the same component (inches). Options = LABEL=EXPR terms joined by |, e.g. W={MODULES WIDE}*9.45|H={MODULES HIGH}*9.45  gives 94.5"W x 47.25"H.  No label: just the expression, e.g. {A}+{B} (do not start with =, the sheet would read it as a formula). Only + - * / ( ) and numbers are allowed.'),
(38,'TYPES','select','Dropdown from Options. A ''-- Custom Input --'' choice is added automatically.'),
(39,'TYPES','dims','Dimension boxes. Options = box labels (e.g. W|H|D). Default = values (e.g. 96|36|8). Proof shows 96"W x 36"H x 8"D.'),
(40,'TYPES','paint','Sherwin-Williams / PMS / Custom swatch picker.'),
(41,'TYPES','finish','Options = standard finishes from Finish_Colors, plus ''Custom Paint'' which opens the SW / PMS picker.'),
(42,'TYPES','vinyl','Oracal series dropdown (Options = allowed series) + swatch picker from Oracal_Colors.'),
(43,'TYPES','db','Swatch picker from a color tab. Options = LED, COIL, TRIMCAP, ACM, ACRYLIC, PVC or CORO.'),
(44,'TYPES','rowmark','Rowmark swatch picker. Options = series to show (e.g. ADA Alternative).'),
(45,'TYPES','pictogram','ADA pictogram picker from ADA_Pictograms.'),
(46,'TYPES','autoqty','Letter count calculated from the TEXT field. Options = the letter-height variable to merge into ''QTY / HEIGHT''.'),
(48,'RULES','RULES',NULL),
(49,'RULES','Options separator','Use | between options in the NEW tabs (lets values contain commas). Product_Schema still uses commas.'),
(50,'RULES','Show_If','Hide a field unless a condition is met, within the same component.  VAR=a|b  (equals one of)   VAR!=a|b  (not)   VAR~=text  (contains).  Join conditions with &.'),
(51,'RULES','Required','Yes = the proof shows a yellow MISSING flag if the field is empty or a swatch isn''t chosen.'),
(52,'RULES','Default_Overrides','VAR=value; VAR=value   (dims use the | format, e.g. CABINET SIZE=120|48|12).'),
(53,'RULES','Do not rename','Tab names and header names are read by Code.gs.'),
(54,'RULES','Proof pages','Assembled products print as numbered pages (max 2 sections per page). ''Generate Proof Package'' saves one PNG per page: product_specs_1.png, product_specs_2.png ...'),
(55,'RULES','Add Components','Every assembled product and component has an ''Add Components'' checklist. Each checked component adds a section to the proof. ''Custom Proof'' in the dropdown starts blank.'),
(56,'RULES','Proof fit','Large assemblies automatically step down text size to fit the 11 x 8.5 proof.'),
(58,'DETAIL DRAWINGS','DETAIL DRAWINGS',NULL),
(59,'DETAIL DRAWINGS','What they do','Small construction drawings (mounting, letter sections, cabinets, footers, panel finishing) drawn in the bottom-right of the art board when a page''s specs match. Up to 3 per page in one column (6 in two). Turn all of them off with Proof_Template > Detail_Drawings = Off, or one at a time with Active = No.'),
(60,'DETAIL DRAWINGS','Components','Detail_Drawings column. Component_IDs the drawing may appear on, comma separated. Blank = any component that has the field named in Match_Rule.'),
(61,'DETAIL DRAWINGS','Match_Rule','Same syntax as Show_If (VAR=a|b, VAR!=a|b, VAR~=text, join with &), plus OR between alternatives, e.g.  MOUNTING=Stud Mount - Flush OR BACKER MOUNTING=Stud Mount.  Blank = always (for the listed Components).'),
(62,'DETAIL DRAWINGS','SVG_Markup','The drawing itself: plain SVG shapes on a 100 x 100 grid (no <svg> wrapper). {VARIABLE} prints that field''s current value, e.g. {EMBED DEPTH} -> 36". {VARIABLE|text} uses text when the field is blank. Keep labels about 5 units tall.'),
(63,'DETAIL DRAWINGS','Order','Detail_Drawings column. Lower numbers print first (bottom of the column) when several drawings match one page.'),
(64,'DETAIL DRAWINGS','In the app','Each product in the Specs panel lists the drawings that matched; uncheck one to leave it off that product''s pages.'),
(66,'DESIGN HELP CENTER','DESIGN HELP CENTER',NULL),
(67,'DESIGN HELP CENTER','What it does','The ? button on step 2 (Specs) opens a plain-text list of the design standards and CorelDRAW how-to''s that apply to the products in the current proof package. Copy, download or print it.'),
(68,'DESIGN HELP CENTER','Design_Guide','One row per rule. Section groups rules in the pop-up (sections print in the order they first appear). Order sorts rules. Active = No hides a rule.'),
(69,'DESIGN HELP CENTER','Components / Match_Rule','Same as Detail_Drawings: Components limits the rule to those Component_IDs (blank = any); Match_Rule uses Show_If syntax with OR. COMPONENT=ID|ID tests the component itself. Both blank = the rule applies to every package.'),
(70,'DESIGN HELP CENTER','Standard / Why / How','Standard = the rule. Why = the reason (shown to new designers). CorelDRAW_How_To = the steps. {VARIABLE} in Standard prints the spec value, e.g. {RETAINER SIZE}.'),
(71,'DESIGN HELP CENTER','Basis','SignOS = from our SignOS equipment / material data. Industry = sign industry standard. House = our design department standard.'),
(73,'COVER PAGE + QA CHECKLIST','COVER PAGE + QA CHECKLIST',NULL),
(74,'COVER PAGE + QA CHECKLIST','Cover page','Page 1 of every package: logo, customer, project, installation location, project info and the list of every product / component with the sections it includes and its proof pages. Proof_Template: Cover_Page On/Off, Cover_Title.'),
(75,'COVER PAGE + QA CHECKLIST','QA checklist','Exported in the zip''s QA_Checklist folder (not for the customer): portrait 8.5 x 11 pages listing every spec of every section with a checkbox and initials line, detail drawings to build to, final checks and the QA Manager sign-off, plus qa_checklist.csv for Excel / Sheets. Proof_Template: QA_Checklist On/Off, QA_Final_Checks (separate checks with |).');
